CREATE DATABASE IF NOT EXISTS smartmart CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE smartmart;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,phone VARCHAR(30) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,photo VARCHAR(255),role ENUM('customer','cashier','admin') DEFAULT 'customer',verified_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE verification_codes(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,channel ENUM('email','phone') NOT NULL,code_hash VARCHAR(255) NOT NULL,expires_at DATETIME NOT NULL,used_at DATETIME NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE products(id INT AUTO_INCREMENT PRIMARY KEY,sku VARCHAR(40) UNIQUE NOT NULL,name VARCHAR(120) NOT NULL,category VARCHAR(80),price DECIMAL(12,2) NOT NULL,stock INT NOT NULL DEFAULT 0,active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sales(id BIGINT AUTO_INCREMENT PRIMARY KEY,receipt_no VARCHAR(32) UNIQUE NOT NULL,user_id INT NOT NULL,total DECIMAL(12,2) NOT NULL,payment_method VARCHAR(30) NOT NULL,status ENUM('paid','cancelled') DEFAULT 'paid',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE sale_items(id BIGINT AUTO_INCREMENT PRIMARY KEY,sale_id BIGINT NOT NULL,product_id INT NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(12,2) NOT NULL,FOREIGN KEY(sale_id) REFERENCES sales(id),FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE audit_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(120) NOT NULL,details TEXT,ip_address VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
